targets.query:
import "strings"

from(bucket: "ftdc")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "ftdc" and
    r._field =~ /^systemMetrics\.disks\..*\.io_time_ms$/
  )
  |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: false)
  |> derivative(unit: 1ms, nonNegative: true)
  |> map(fn: (r) => ({
      r with _value: r._value * 100.0  // convert to percentage
  }))
  |> map(fn: (r) => ({
      r with _field: strings.replaceAll(
        v: strings.replaceAll(
          v: r._field,
          t: "systemMetrics.disks.",
          u: ""
        ),
        t: ".io_time_ms",
        u: ""
      )
  }))
